                when coalesce(p_reason, '') <> '' then
                    format('Bị từ chối báo cáo test (thu hồi %s Credit tạm ứng): %s', v_deduct, p_reason)
                else
                    format('Bị từ chối báo cáo test (thu hồi %s Credit tạm ứng)', v_deduct)
            end,
            v_new_balance
        );
    end if;

    update public.tester_reports
    set status = 'rejected',
        rejection_reason = p_reason,
        reason_code = v_final_reason_code,
        reviewed_at = now(),
        provisional_clawed = v_deduct
    where id = p_report_id;

    insert into public.report_review_events (
        report_id, campaign_id, tester_id, owner_id, reviewer_id, event_type, reason
    ) values (
        v_report.id, v_camp.id, v_report.user_id, v_camp.owner_id, v_caller_id, 'reject', p_reason
    );

    if coalesce(v_report.submission_context, 'app_test') = 'app_test' then
        update public.checkins
        set note = 'Bị từ chối: ' || coalesce(p_reason, 'Không đạt yêu cầu')
        where campaign_id = v_camp.id
          and user_id = v_report.user_id
          and checkin_date = v_report_date;
    end if;

    insert into public.notifications (user_id, title, message, type, data)
    values (
        v_report.user_id,
        'Báo cáo kiểm thử bị từ chối ❌',
        case
            when coalesce(p_reason, '') <> '' then
                format('Báo cáo của bạn cho ứng dụng "%s" bị từ chối với lý do: %s. %s Credit tạm ứng đã bị thu hồi.',
                       v_camp.app_name, p_reason, v_deduct)
            else
                format('Báo cáo của bạn cho ứng dụng "%s" bị từ chối. %s Credit tạm ứng đã bị thu hồi.',
                       v_camp.app_name, v_deduct)
        end,
        'report',
        jsonb_build_object(
            'report_id', v_report.id,
            'campaign_id', v_camp.id,
            'status', 'rejected',
            'reason', p_reason,
            'reason_code', v_final_reason_code,
            'clawed_credits', v_deduct
        )
    );

    -- Kiểm tra hoàn quỹ nếu là báo cáo nhiệm vụ
    if v_report.mission_id is not null then
        perform public._check_and_refund_mission_escrow(v_report.mission_id);
    end if;

    perform set_config('app.reviewing_report', 'false', true);

    return jsonb_build_object(
        'success', true,
        'report_id', v_report.id,
        'campaign_id', v_camp.id,
        'tester_id', v_report.user_id,
        'status', 'rejected',
        'credits_deducted', v_deduct,
        'clawed_credits', v_deduct,
        'tester_balance', v_new_balance,
        'new_balance', v_new_balance,
        'reason_code', v_final_reason_code
    );
end;
$function$;

